16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.time.Period;
27	import java.time.temporal.ChronoUnit;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "title")
42	    private String title;
43	
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "address_line1")
49	    private String addressLine1;
50	
51	    @Column(name = "address_line2")
52	    private String addressLine2;
53	
54	    @Column(name = "city")
55	    @NotEmpty
56	    private String city;
57	
58	    @Column(name = "postcode")
59	    private String postcode;
60	
61	    @Column(name = "telephone")
62	    @NotEmpty
63	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
64	    private String telephone;
65	
66	    @Column(name = "email")
67	    @Email
68	    private String email;
69	
70	    @Column(name = "registration_date")
71	    private LocalDate registrationDate;
72	
73	    @Column(name = "birth_date")
74	    private LocalDate birthDate;
75	
76	    @Column(name = "customer_code")
77	    private String customerCode;
78	
79	    @Column(name = "household_id")
80	    private String householdId;
81	
82	    @Column(name = "namesake_count")
83	    private Integer namesakeCount;
84	
85	    @Column(name = "bulk_signup_warning")
86	    private Boolean bulkSignupWarning;
87	
88	    @Column(name = "household_size")
89	    private Integer householdSize;
90	
91	    @Column(name = "possible_duplicate")
92	    private Boolean possibleDuplicate;
93	
94	    @Column(name = "possible_duplicate_of")
95	    private Integer possibleDuplicateOf;
96	
97	    @Column(name = "deleted", nullable = false)
98	    private boolean deleted;
99	
100	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
101	    private Set<Pet> pets;
102	
103	    public String getTitle() {
104	        return this.title;
105	    }
106	
107	    public void setTitle(String title) {
108	        this.title = title;
109	    }
110	
111	    /**
112	     * The owner's salutation: the {@link #getTitle() title} and lastName separated by a single
113	     * space when a title is present, or just the lastName when no title was given.
114	     */
115	    public String getSalutation() {
116	        if (this.title == null || this.title.isEmpty()) {
117	            return this.getLastName();
118	        }
119	        return this.title + " " + this.getLastName();
120	    }
121	
122	    public String getAddress() {
123	        return this.address;
124	    }
125	
126	    public void setAddress(String address) {
127	        this.address = address;
128	    }
129	
130	    public String getAddressLine1() {
131	        return this.addressLine1;
132	    }
133	
134	    public void setAddressLine1(String addressLine1) {
135	        this.addressLine1 = addressLine1;
136	    }
137	
138	    public String getAddressLine2() {
139	        return this.addressLine2;
140	    }
141	
142	    public void setAddressLine2(String addressLine2) {
143	        this.addressLine2 = addressLine2;
144	    }
145	
146	    public String getCity() {
147	        return this.city;
148	    }
149	
150	    public void setCity(String city) {
151	        this.city = city;
152	    }
153	
154	    public String getPostcode() {
155	        return this.postcode;
156	    }
157	
158	    public void setPostcode(String postcode) {
159	        this.postcode = postcode;
160	    }
161	
162	    public String getTelephone() {
163	        return this.telephone;
164	    }
165	
166	    public void setTelephone(String telephone) {
167	        this.telephone = telephone;
168	    }
169	
170	    public String getEmail() {
171	        return this.email;
172	    }
173	
174	    public void setEmail(String email) {
175	        this.email = email == null ? null : email.toLowerCase();
176	    }
177	
178	    public LocalDate getRegistrationDate() {
179	        return this.registrationDate;
180	    }
181	
182	    public void setRegistrationDate(LocalDate registrationDate) {
183	        this.registrationDate = registrationDate;
184	    }
185	
186	    public LocalDate getBirthDate() {
187	        return this.birthDate;
188	    }
189	
190	    public void setBirthDate(LocalDate birthDate) {
191	        this.birthDate = birthDate;
192	    }
193	
194	    /**
195	     * The owner's age band derived from {@link #birthDate} relative to the
196	     * {@link #registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
197	     * and {@code 'SENIOR'} at 65 or older. Returns {@code null} when no birthDate is set. The age
198	     * is the number of complete years between the birthDate and the registrationDate (or the
199	     * current date when the registrationDate is not yet set).
200	     */
201	    public String getAgeBand() {
202	        if (this.birthDate == null) {
203	            return null;
204	        }
205	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
206	        int years = Period.between(this.birthDate, reference).getYears();
207	        if (years < 18) {
208	            return "MINOR";
209	        }
210	        if (years < 65) {
211	            return "ADULT";
212	        }
213	        return "SENIOR";
214	    }
215	
216	    public String getCustomerCode() {
217	        return this.customerCode;
218	    }
219	
220	    public void setCustomerCode(String customerCode) {
221	        this.customerCode = customerCode;
222	    }
223	
224	    public String getHouseholdId() {
225	        return this.householdId;
226	    }
227	
228	    public void setHouseholdId(String householdId) {
229	        this.householdId = householdId;
