268	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
269	        this.possibleDuplicateOf = possibleDuplicateOf;
270	    }
271	
272	    /**
273	     * Whether the owner has been soft-deleted. A newly created owner is {@code false};
274	     * {@code DELETE /api/owners/{id}} marks the owner {@code deleted} while retaining the row, and
275	     * a deleted owner is ignored by the create endpoint's duplicate and identity checks.
276	     */
277	    public boolean isDeleted() {
278	        return this.deleted;
279	    }
280	
281	    public void setDeleted(boolean deleted) {
282	        this.deleted = deleted;
283	    }
284	
285	    /**
286	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
287	     */
288	    public String getDisplayName() {
289	        return this.getLastName() + ", " + this.getFirstName();
290	    }
291	
292	    /**
293	     * The owner's initials: the upper-cased first letters of firstName and lastName,
294	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
295	     */
296	    public String getInitials() {
297	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
298	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
299	    }
300	
301	    /**
302	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
303	     * last two digits of the registrationDate year, e.g. {@code 'NSW-3C1A9F2B-M26'}.
304	     */
305	    public String getMembershipNumber() {
306	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
307	    }
308	
309	    /**
310	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
311	     * contained in the owner's {@link #customerCode}.
312	     */
313	    public int getCheckDigit() {
314	        return luhnCheckDigit(this.customerCode);
315	    }
316	
317	    /**
318	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
319	     * contained in {@code value}. Reading the digits right to left, every second one is
320	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
321	     * digits are summed, and the check digit is the amount that must be added to that sum to
322	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
323	     * the digit is taken over exactly the digits the string carries.
324	     */
325	    private static int luhnCheckDigit(String value) {
326	        int sum = 0;
327	        boolean doubling = true;
328	        for (int i = value.length() - 1; i >= 0; i--) {
329	            char c = value.charAt(i);
330	            if (c < '0' || c > '9') {
331	                continue;
332	            }
333	            int digit = c - '0';
334	            if (doubling) {
335	                digit *= 2;
336	                if (digit > 9) {
337	                    digit -= 9;
338	                }
339	            }
340	            sum += digit;
341	            doubling = !doubling;
342	        }
343	        return (10 - (sum % 10)) % 10;
344	    }
345	
346	    /** Fixed city-to-region table used to derive an owner's locality. */
347	    private static final Map<String, String> CITY_REGION = Map.of(
348	        "Sydney", "NSW",
349	        "Melbourne", "VIC",
350	        "Brisbane", "QLD");
351	
352	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
353	    public static final String UNKNOWN_REGION = "UNKNOWN";
354	
355	    /**
356	     * The canonical region for a city, derived from the fixed city-to-region table
357	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
358	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
359	     * source of the city-to-region mapping, shared by every rule that is keyed by
360	     * region so the mapping is never re-derived elsewhere.
361	     */
362	    public static String regionOf(String city) {
363	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
364	    }
365	
366	    /**
367	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
368	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
369	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
370	     * known region). Locality is read from the region-and-hash identity so it never re-derives
371	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
372	     */
373	    public String getLocality() {
374	        if (this.customerCode == null) {
375	            return UNKNOWN_REGION;
376	        }
377	        int dash = this.customerCode.indexOf('-');
378	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
379	    }
380	
381	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
382	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
383	        "NSW", "Australia/Sydney",
384	        "VIC", "Australia/Melbourne",
385	        "QLD", "Australia/Brisbane");
386	
387	    /**
388	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
389	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
390	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
391	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
392	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
393	     */
394	    public String getTimezone() {
395	        return REGION_TIMEZONE.get(getLocality());
396	    }
397	
398	    /**
399	     * The region derived from this owner's postcode alone: the region whose fixed
400	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
401	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
402	     * component built into the owner's customer code at creation and, through it, the source of the
403	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
404	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
405	     */
406	    public String getRegion() {
407	        return regionOfPostcode(this.postcode);
408	    }
409	
410	    /**
411	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
412	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
413	     * no known range.
414	     */
415	    private static String regionOfPostcode(String postcode) {
416	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
417	            return null;
418	        }
419	        int value = Integer.parseInt(postcode);
420	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
421	            int[] range = entry.getValue();
422	            if (value >= range[0] && value <= range[1]) {
423	                return entry.getKey();
424	            }
425	        }
426	        return null;
427	    }
428	
429	    /**
430	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
431	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
432	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
433	     */
434	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
435	        "NSW", new int[] {2000, 2099},
436	        "VIC", new int[] {3000, 3099},
437	        "QLD", new int[] {4000, 4099});
438	
439	    /**
440	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
441	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
442	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
443	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
444	     * city with no known region accepts any 4-digit postcode.
445	     */
446	    public boolean isPostcodeValid() {
447	        if (this.postcode == null) {
448	            return true;
449	        }
450	        if (!this.postcode.matches("[0-9]{4}")) {
451	            return false;
452	        }
453	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
454	        if (range == null) {
455	            return true;
456	        }
457	        int value = Integer.parseInt(this.postcode);
458	        return value >= range[0] && value <= range[1];
459	    }
460	
461	    /**
462	     * The national (subscriber) digit count required by each known country calling code, keyed by
463	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
464	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
465	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
466	     * re-derived elsewhere.
467	     */
468	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
469	        "1", 10,
470	        "61", 9);
471	
472	    /**
473	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
474	     * E.164 digit string, choosing the longest matching code known to
475	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
476	     * country code. This is the single place a country code is read from an E.164 number, so every
477	     * rule keyed by that code shares one derivation.
478	     */
479	    private static String countryCodeOf(String e164Digits) {
480	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
481	            .filter(e164Digits::startsWith)
482	            .max(Comparator.comparingInt(String::length))
483	            .orElse(null);
484	    }
485	
486	    /**
487	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
488	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
489	     * known code wins; a number whose country code is not recognised passes this check (its length is
490	     * then governed only by the general E.164 bound), while a recognised code must be followed by
491	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
492	     */
493	    public static boolean hasValidNationalLength(String e164Digits) {
494	        String countryCode = countryCodeOf(e164Digits);
495	        if (countryCode == null) {
496	            return true;
497	        }
498	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
499	    }
500	
501	    /**
502	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
503	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
504	     * gain 3 when the owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. The email,
505	     * namesake and household factors are available on creation; the tenure factor is reached only
506	     * once tenure grows beyond 365 days.
507	     */
508	    public Integer getMembershipPoints() {
509	        int points = 0;
510	        if (hasEmail()) {
511	            points += 2;
512	        }
513	        if (hasNoNamesakes()) {
514	            points += 1;
515	        }
516	        if (hasLargeHousehold()) {
517	            points += 2;
518	        }
519	        if (hasTenureBeyondOneYear()) {
520	            points += 3;
521	        }
522	        return points;
523	    }
524	
525	    /**
526	     * The owner's membership level, a number from 1 to 4 derived from {@linkplain #getMembershipPoints()
527	     * membershipPoints}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or
528	     * more.
529	     */
530	    public Integer getMembershipLevel() {
531	        int points = getMembershipPoints();
532	        if (points >= 6) {
533	            return 4;
534	        }
535	        if (points >= 4) {
536	            return 3;
537	        }
538	        if (points >= 2) {
539	            return 2;
540	        }
541	        return 1;
542	    }
543	
544	    /**
545	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
546	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
547	     * known, is treated as not a large household.
548	     */
549	    private boolean hasLargeHousehold() {
550	        return this.householdSize != null && this.householdSize >= 3;
551	    }
552	
553	    /**
554	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
555	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
556	     * email presence so the check is never re-derived elsewhere.
557	     */
558	    private boolean hasEmail() {
559	        return this.email != null && !this.email.isEmpty();
560	    }
561	
562	    /**
563	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
564	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
565	     * not known, is treated as not unique.
566	     */
567	    private boolean hasNoNamesakes() {
568	        return this.namesakeCount != null && this.namesakeCount == 0;
569	    }
570	
571	    /**
572	     * Whether this owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. A newly created owner
573	     * (zero tenure) does not qualify; the threshold is crossed only once tenure grows beyond one year.
574	     */
575	    private boolean hasTenureBeyondOneYear() {
576	        return this.getTenureDays() > 365;
577	    }
578	
579	    /**
580	     * The owner's tenure in whole days: the number of days between the {@link #registrationDate} and
581	     * the current date, or {@code 0} when the registrationDate is not yet set (a newly created owner has
582	     * zero tenure). Never negative.
583	     */
584	    public long getTenureDays() {
585	        if (this.registrationDate == null) {
586	            return 0;
587	        }
588	        return Math.max(0, ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()));
589	    }
590	
591	    /**
592	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
593	     * otherwise {@code 'PHONE'}.
594	     */
595	    public String getContactPreference() {
596	        return hasEmail() ? "EMAIL" : "PHONE";
597	    }
598	
599	    /**
600	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
601	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
602	     * the national digits grouped into threes from the left separated by spaces,
603	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
604	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
605	     * E.164 form, or carries no known country code.
606	     */
607	    public String getTelephoneDisplay() {
608	        if (this.telephone == null || !this.telephone.startsWith("+")) {
609	            return this.telephone;
610	        }
611	        String digits = this.telephone.substring(1);
612	        String countryCode = countryCodeOf(digits);
613	        if (countryCode == null) {
614	            return this.telephone;
615	        }
616	        String national = digits.substring(countryCode.length());
617	        StringBuilder groups = new StringBuilder();
618	        for (int i = 0; i < national.length(); i += 3) {
619	            if (groups.length() > 0) {
620	                groups.append(' ');
621	            }
622	            groups.append(national, i, Math.min(i + 3, national.length()));
623	        }
624	        return "+" + countryCode + " " + groups;
625	    }
626	
627	    /**
628	     * The owner's identity key: the single derived value used for duplicate detection.
629	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
630	     * empty string when absent) and the householdId (or the empty string when the owner
631	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
632	     * Two owners are duplicates only when their whole identity keys are equal.
633	     */
634	    public String getIdentityKey() {
635	        String telephonePart = this.telephone == null ? "" : this.telephone;
636	        String emailPart = this.email == null ? "" : this.email;
637	        String householdPart = this.householdId == null ? "" : this.householdId;
638	        return telephonePart + "|" + emailPart + "|" + householdPart;
639	    }
640	
641	    protected Set<Pet> getPetsInternal() {
642	        if (this.pets == null) {
643	            this.pets = new HashSet<>();
644	        }
645	        return this.pets;
646	    }
647	
648	    protected void setPetsInternal(Set<Pet> pets) {
649	        this.pets = pets;
650	    }
651	
652	    public List<Pet> getPets() {
653	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
654	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
655	        return Collections.unmodifiableList(sortedPets);
656	    }
657	
658	    public void setPets(List<Pet> pets) {
659	        this.pets = new HashSet<>(pets);
660	    }
661	
662	    public void addPet(Pet pet) {
663	        getPetsInternal().add(pet);
664	        pet.setOwner(this);
665	    }
666	
667	    /**
668	     * Return the Pet with the given name, or null if none found for this Owner.
669	     *
670	     * @param name to test
671	     * @return true if pet name is already in use
672	     */
673	    public Pet getPet(String name) {
674	        return getPet(name, false);
675	    }
676	
677	    /**
678	     * Return the Pet with the given name, or null if none found for this Owner.
679	     *
680	     * @param name to test
681	     * @return true if pet name is already in use
682	     */
683	    public Pet getPet(String name, boolean ignoreNew) {
684	        name = name.toLowerCase();
685	        for (Pet pet : getPetsInternal()) {
686	            if (!ignoreNew || !pet.isNew()) {
687	                String compName = pet.getName();
688	                compName = compName.toLowerCase();
689	                if (compName.equals(name)) {
690	                    return pet;
691	                }
692	            }
693	        }
694	        return null;
695	    }
696	
697	    public Pet getPet(Integer petId) {
698	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
699	    }
700	
701	    @Override
702	    public String toString() {
703	        return new ToStringCreator(this)
704	
705	            .append("id", this.getId())
706	            .append("new", this.isNew())
707	            .append("lastName", this.getLastName())
708	            .append("firstName", this.getFirstName())
709	            .append("address", this.address)
710	            .append("city", this.city)
711	            .append("telephone", this.telephone)
712	            .append("email", this.email)
713	            .toString();
714	    }
715	}
