156	    /**
157	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
158	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
159	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
160	     * postcode is checked against its city's region, a registration date in the future is rejected,
161	     * and the effective registration date (the supplied one, or today when none was given) is rolled
162	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
163	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
164	     * otherwise.
165	     */
166	    private HttpStatus normalizeAndValidate(Owner owner) {
167	        if (!normalizeAddress(owner)) {
168	            return HttpStatus.BAD_REQUEST;
169	        }
170	        String telephone = toE164(owner.getTelephone());
171	        if (telephone == null) {
172	            return HttpStatus.BAD_REQUEST;
173	        }
174	        owner.setTelephone(telephone);
175	        if (isDisposableEmail(owner.getEmail())) {
176	            return HttpStatus.BAD_REQUEST;
177	        }
178	        if (!owner.isPostcodeValid()) {
179	            return HttpStatus.BAD_REQUEST;
180	        }
181	        if (owner.getRegistrationDate() != null
182	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
183	            return HttpStatus.BAD_REQUEST;
184	        }
185	        LocalDate effectiveDate = owner.getRegistrationDate() != null
186	            ? owner.getRegistrationDate() : LocalDate.now();
187	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
188	        return null;
189	    }
190	
191	    /**
192	     * Normalize the owner's supplied address into its canonical stored form and report whether an
193	     * address was supplied at all. The owner may supply its address either as the structured
194	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
195	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
196	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
197	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
198	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
199	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
200	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
201	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
202	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
203	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
204	     * create must be rejected with {@code 400 Bad Request}.
205	     */
206	    private boolean normalizeAddress(Owner owner) {
207	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
208	        if (!line1.isEmpty()) {
209	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
210	            owner.setAddressLine1(line1);
211	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
212	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
213	            return true;
214	        }
215	        String address = addressNormalizer.normalize(owner.getAddress());
216	        if (address.isEmpty()) {
217	            return false;
218	        }
219	        owner.setAddressLine1(null);
220	        owner.setAddressLine2(null);
221	        owner.setAddress(address);
222	        return true;
223	    }
